// deriveSearchVerifyCommand walks from the subject's own directory towards the repository root and
// stops at the FIRST manifest that licenses a narrow command.
//
// A manifest that exists but licenses nothing generally does not stop the walk: a `Cargo.toml` that
// is only a workspace stanza, or a monorepo leaf `package.json` with no test runner in it, is evidence
// about the tree, not about how to run a test, so the walk continues outward to the manifest that is.
// Gradle is different once a wrapper and settings establish a project: an ancestor project can
// accept the same test pattern without owning that project's sources, so a Gradle project that
// declines blocks ancestor Gradle derivation. Other ecosystems still participate farther up the
// tree, and a manifest without a runnable Gradle build blocks nothing.
func deriveSearchVerifyCommand(subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	dir := path.Dir(subject.sourcePath)
	if dir == "." || dir == "/" {
		dir = ""
	}
	gradleBlocked := false
	for depth := 0; depth <= searchVerifyMaxDepth; depth++ {
		for _, derivation := range searchVerifyDerivations {
			if gradleBlocked && derivation.gradle {
				continue
			}
			if command := derivation.run(dir, subject, evidence); command != nil {
				return command
			}
		}
		if searchVerifyBlocksAncestorGradle(dir, evidence) {
			gradleBlocked = true
		}
		if dir == "" {
			break
		}
		parent := path.Dir(dir)
		if parent == "." || parent == "/" || parent == dir {
			dir = ""
			continue
		}
		dir = parent
	}
	return nil
}

// searchVerifyDerivations is the ordered list of build systems consulted at each directory level.
// Language manifests come before generic ones: a Rust crate with a convenience Makefile must yield
// the crate's own test command, not `make test`.
var searchVerifyDerivations = []struct {
	run    func(string, searchVerifySubject, *searchVerifyEvidence) *SearchVerifyCommand
	gradle bool
}{
	{run: deriveSearchVerifyCargo},
	{run: deriveSearchVerifyGo},
	{run: deriveSearchVerifyMaven},
	{run: deriveSearchVerifyGradle, gradle: true},
	{run: deriveSearchVerifyNode},
	{run: deriveSearchVerifyComposer},
	{run: deriveSearchVerifyPytest},
	{run: deriveSearchVerifyRuby},
	{run: deriveSearchVerifyCMake},
	{run: deriveSearchVerifyMake},
}

// deriveSearchVerifySuiteCommand is the whole-suite fallback consulted only when no narrow command
// exists. It walks from the subject's directory towards the root exactly like the narrow derivation
// and returns the first recognized ecosystem's canonical suite command. Unlike the narrow tier it
// does NOT require a covering test: its whole point is the case where the payload found none.
func deriveSearchVerifySuiteCommand(subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	dir := path.Dir(subject.sourcePath)
	if dir == "." || dir == "/" {
		dir = ""
	}
	gradleBlocked := false
	for depth := 0; depth <= searchVerifyMaxDepth; depth++ {
		for _, derivation := range searchVerifySuiteDerivations {
			if gradleBlocked && derivation.gradle {
				continue
			}
			if command := derivation.run(dir, evidence); command != nil {
				return command
			}
		}
		if searchVerifyBlocksAncestorGradle(dir, evidence) {
			gradleBlocked = true
		}
		if dir == "" {
			break
		}
		parent := path.Dir(dir)
		if parent == "." || parent == "/" || parent == dir {
			dir = ""
			continue
		}
		dir = parent
	}
	return nil
}

// searchVerifySuiteDerivations mirrors searchVerifyDerivations, language-specific before generic, so
// a Rust crate with a convenience Makefile still yields `cargo test`, not `make test`.
var searchVerifySuiteDerivations = []struct {
	run    func(string, *searchVerifyEvidence) *SearchVerifyCommand
	gradle bool
}{
	{run: deriveSearchVerifySuiteCargo},
	{run: deriveSearchVerifySuiteGo},
	{run: deriveSearchVerifySuiteMaven},
	{run: deriveSearchVerifySuiteGradle, gradle: true},
	{run: deriveSearchVerifySuiteNode},
	{run: deriveSearchVerifySuiteComposer},
	{run: deriveSearchVerifySuitePytest},
	{run: deriveSearchVerifySuiteRuby},
	{run: deriveSearchVerifySuiteCMake},
	{run: deriveSearchVerifySuiteMake},
}

// searchVerifySuiteCommand builds a whole-suite command, labeling both the target (no covering test
// was found) and the derivation (whole suite) so the reader knows it is unfiltered and slow.
func searchVerifySuiteCommand(dir, command, derived string) *SearchVerifyCommand {
	return searchVerifySuiteCommandLiteral(searchVerifyRunIn(dir, command), derived)
}

// searchVerifySuiteCommandLiteral is searchVerifySuiteCommand for a derivation that has already
// decided where the command runs. Maven's reactor is the case: a module is addressed from the
// repository root with `-pl`, so prefixing a `cd` into the module would be wrong rather than
// merely redundant.
func searchVerifySuiteCommandLiteral(command, derived string) *SearchVerifyCommand {
	return &SearchVerifyCommand{
		Command:     command,
		Targets:     "whole test suite (no covering test identified)",
		DerivedFrom: derived + " (whole suite)",
	}
}

func deriveSearchVerifySuiteCargo(dir string, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	manifest := searchVerifyJoin(dir, "Cargo.toml")
	content, ok := evidence.file(manifest)
	if !ok || (!strings.Contains(content, "[package]") && !strings.Contains(content, "[workspace]")) {
		return nil
	}
	return searchVerifySuiteCommand(dir, "cargo test", manifest)
}

func deriveSearchVerifySuiteGo(dir string, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	manifest := searchVerifyJoin(dir, "go.mod")
	if !evidence.exists(manifest) {
		return nil
	}
	return searchVerifySuiteCommand(dir, "go test ./...", manifest+" module")
}

func deriveSearchVerifySuiteMaven(dir string, evidence *searchVerifyEvidence) *SearchVerifyCommand {
	manifest := searchVerifyJoin(dir, "pom.xml")
	if !evidence.exists(manifest) {
		return nil
	}
	return searchVerifySuiteCommandLiteral(searchVerifyMavenCommand(dir, "test", evidence), manifest)
}

func searchVerifyGradleManifest(dir string, evidence *searchVerifyEvidence) string {
	for _, name := range []string{"build.gradle", "build.gradle.kts"} {
		manifest := searchVerifyJoin(dir, name)
		if evidence.exists(manifest) {
			return manifest
		}
	}
	return ""
}

func searchVerifyBlocksAncestorGradle(dir string, evidence *searchVerifyEvidence) bool {
	return searchVerifyGradleManifest(dir, evidence) != ""
}

type searchVerifyGradleTarget struct {
	wrapperDir    string
	commandPrefix string
	project       string
	derivedFrom   string
	selectsBuild  bool
}

func (target searchVerifyGradleTarget) testCommand(qualifyRoot bool) string {
	task := "test"
	if target.project != "" {
		task = target.project + ":test"
	} else if qualifyRoot && !target.selectsBuild {
		task = ":test"
	}
	return target.commandPrefix + " " + shellQuote(task)
}

func searchVerifyGradleTargetForDir(dir string, evidence *searchVerifyEvidence) (searchVerifyGradleTarget, bool) {
	manifest := searchVerifyGradleManifest(dir, evidence)
	if manifest == "" {
		return searchVerifyGradleTarget{}, false
	}
	wrapperDir, wrapperPath, ok := searchVerifyAncestorFile(dir, "gradlew", evidence)
	if !ok {
		return searchVerifyGradleTarget{}, false
	}
	target := searchVerifyGradleTarget{
		wrapperDir:    wrapperDir,
		commandPrefix: "./gradlew",
		derivedFrom:   manifest + " + " + wrapperPath,
	}
